#!/usr/bin/env python3
"""Уроки теорії (data/lessons.json) і каталог знаків (data/signs.json)."""
import json, sys

R = sys.argv[1]
L = ("uk", "nl", "fr", "en")
T = lambda t: dict(zip(L, t))


def C(id, title, body, art, serious=False, sign=None, image=None, terms=()):
    d = {"id": id, "title": T(title), "body": T(body), "article": art, "serious": serious,
         "terms": [{"nl": n, "fr": f} for n, f in terms]}
    if sign:
        d["sign"] = sign
    if image:
        d["image"] = image
    return d


